# Modul: o6_22 – Stallhaltung, Gruppenhaltung, Platzangebot und Freilandhaltung
package oepul.o6_22

# ---------------------------------------------------------------------------
# Gewichtsklassen und Mindestflächen (O622-SPACE-002, O622-SPACE-003, O622-SPACE-005)
# ---------------------------------------------------------------------------

above_lower(lower, w) if {
	lower == null
	is_number(w)
}

above_lower(lower, w) if {
	is_number(lower)
	w > lower
}

below_upper(upper, w) if {
	upper == null
	is_number(w)
}

below_upper(upper, w) if {
	is_number(upper)
	w <= upper
}

# Gewichtsklasse laut Tabelle Kapitel 6.2.5 anhand des Durchschnittsgewichts der Gruppe.
weight_class(w) := row if {
	some row in space.piglets_fattening
	above_lower(row.min_weight_kg_exclusive, w)
	below_upper(row.max_weight_kg_inclusive, w)
}

sow_space_row(animal_type) := row if {
	some row in space.sows
	row.animal_type == animal_type
}

# O622-DOC-002: maximal mögliche Tierzahl je Stallabteil (Belegungsplan).
max_animals_in_pen(area_m2, avg_weight_kg) := floor((area_m2 + 0.000001) / weight_class(avg_weight_kg).total_area_m2)

max_sows_in_pen(area_m2, animal_type) := floor((area_m2 + 0.000001) / sow_space_row(animal_type).total_area_m2)

# O622-SPACE-002: geforderte nutzbare Gesamtfläche einer Bucht (Ferkel, Jung- und Mastschweine).
required_total_area_fattening(pen) := r4(pen.animal_count * weight_class(pen.average_weight_kg).total_area_m2)

# O622-SPACE-001: eingestreute Liegefläche mindestens 40 % der geforderten Gesamtfläche.
required_littered_lying_area_fattening(pen) := r4(required_total_area_fattening(pen) * space.thresholds.min_littered_lying_share_of_required_total)

# O622-SPACE-005: Sauenbuchten (Zuchtsauen 3,00/1,30 m², gedeckte Jungsauen 2,00/0,95 m²).
sow_counts(pen) := object.get(pen, "sow_counts", {})

required_total_area_sows(pen) := r4(sum([x | some t, n in sow_counts(pen); x := n * sow_space_row(t).total_area_m2]))

required_lying_area_sows(pen) := r4(sum([x | some t, n in sow_counts(pen); x := n * sow_space_row(t).lying_area_m2]))

# O622-STALL-004: nutzbare Gesamtfläche = befestigte Flächen mit ständigem Zugang.
effective_usable_area(pen) := r4((object.get(pen, "usable_total_area_m2", 0) - object.get(pen, "unpaved_area_included_m2", 0)) - closed_run_area(pen))

closed_run_area(pen) := object.get(pen, "outdoor_run_area_m2", 0) if object.get(pen, "outdoor_run_permanent_access", true) == false

closed_run_area(pen) := 0 if object.get(pen, "outdoor_run_permanent_access", true) != false

# ---------------------------------------------------------------------------
# Buchten der Stallhaltung
# ---------------------------------------------------------------------------

stall_housed(g) if object.get(g, ["housing", "housing_type"], "unknown") in {"stall", "mixed"}

free_range_housed(g) if object.get(g, ["housing", "housing_type"], "unknown") in {"pasture", "mixed"}

group_pens(g) := object.get(g, ["housing", "stall", "pens"], [])

# O622-GRP-008: Sauen außerhalb der Gruppenhaltungspflicht – Einstreu und Platzbedarf
# müssen in diesen Zeiten nicht erfüllt sein.
pen_exempt(g, pen) if {
	group_measure_category(g) == "zuchtsauen"
	object.get(pen, "outside_group_housing_obligation", false) == true
}

checked_pen(g, pen) if {
	g.housing.housing_type in {"stall", "mixed"}
	not pen_exempt(g, pen)
}

is_fattening_group(g) if group_measure_category(g) in {"ferkel", "mastschweine"}

is_sow_group(g) if group_measure_category(g) == "zuchtsauen"

bedding_row(code) := row if {
	some row in lists.bedding_materials_examples
	row.code == code
}

# O622-ENR-001: Beschäftigungsmaterial (Gras, Stroh oder Heu) jederzeit verfügbar.
enrichment_ok(pen) if {
	bedding_row(pen.bedding_material).counts_as_straw_or_hay_bedding == true
	object.get(pen, "minimal_bedding", false) == false
}

enrichment_ok(pen) if {
	object.get(pen, "enrichment_permanently_available", false) == true
	object.get(pen, "enrichment_material", "") in lists.enrichment_materials
}

# ---------------------------------------------------------------------------
# Gruppenhaltung Sauen (THVO) – O622-GRP-006, O622-GRP-007, O622-GRP-009
# ---------------------------------------------------------------------------

sow_transitional_rule_applicable(sgh) if {
	object.get(sgh, "stall_built_or_rebuilt_since_2013", true) == false
	object.get(sgh, "sufficient_group_space_without_construction", true) == false
	year <= params.sow_group_housing_transition_until_year
}

required_group_start_days_after_mating(sgh) := params.sow_group_housing_transitional_start_days_after_mating if sow_transitional_rule_applicable(sgh)

required_group_start_days_after_mating(sgh) := params.sow_group_housing_start_days_after_mating if not sow_transitional_rule_applicable(sgh)

required_group_end_days_before_farrowing(sgh) := params.sow_group_housing_transitional_end_days_before_farrowing if sow_transitional_rule_applicable(sgh)

required_group_end_days_before_farrowing(sgh) := params.sow_group_housing_end_days_before_farrowing if not sow_transitional_rule_applicable(sgh)

# Gruppenhaltungspflicht an einem Tag des Trächtigkeitszyklus.
sow_group_housing_required(sgh, days_after_mating, days_before_farrowing) if {
	days_after_mating >= required_group_start_days_after_mating(sgh)
	days_before_farrowing >= required_group_end_days_before_farrowing(sgh)
}

# ---------------------------------------------------------------------------
# Freilandhaltung – O622-FREE-001 bis O622-FREE-010
# ---------------------------------------------------------------------------

free_range(g) := object.get(g, ["housing", "free_range"], {})

free_range_reference_area_ha(fr) := fr.rotational_total_area_ha if {
	object.get(fr, "rotational_paddocks", false) == true
	is_number(object.get(fr, "rotational_total_area_ha", null))
}

free_range_reference_area_ha(fr) := object.get(fr, "unpaved_area_ha", 0) if {
	not object.get(fr, "rotational_paddocks", false) == true
}

free_range_reference_area_ha(fr) := object.get(fr, "unpaved_area_ha", 0) if {
	object.get(fr, "rotational_paddocks", false) == true
	not is_number(object.get(fr, "rotational_total_area_ha", null))
}

free_range_max_gve_per_ha(fr) := fr.water_permit_max_gve_per_ha if is_number(object.get(fr, "water_permit_max_gve_per_ha", null))

free_range_max_gve_per_ha(fr) := params.free_range_default_max_gve_per_ha if not is_number(object.get(fr, "water_permit_max_gve_per_ha", null))

free_range_gve(g) := object.get(free_range(g), "enclosure_gve", group_gve_declared(g))

free_range_stocking_gve_per_ha(g) := r4(free_range_gve(g) / free_range_reference_area_ha(free_range(g))) if free_range_reference_area_ha(free_range(g)) > 0

# ---------------------------------------------------------------------------
# Verstöße Stallhaltung
# ---------------------------------------------------------------------------

violations contains {
	"rule_id": "O622-SPACE-002",
	"message": sprintf("Gruppe %v, Bucht %v: nutzbare Gesamtfläche %v m² < gefordert %v m²", [group_label(i, g), pen.pen_id, effective_usable_area(pen), required_total_area_fattening(pen)]),
} if {
	some i, g in pig_groups
	is_fattening_group(g)
	some pen in group_pens(g)
	checked_pen(g, pen)
	effective_usable_area(pen) < required_total_area_fattening(pen)
}

violations contains {
	"rule_id": "O622-SPACE-001",
	"message": sprintf("Gruppe %v, Bucht %v: eingestreute Liegefläche %v m² < 40 %% der geforderten Gesamtfläche (%v m²)", [group_label(i, g), pen.pen_id, object.get(pen, "littered_lying_area_m2", 0), required_littered_lying_area_fattening(pen)]),
} if {
	some i, g in pig_groups
	is_fattening_group(g)
	some pen in group_pens(g)
	checked_pen(g, pen)
	object.get(pen, "littered_lying_area_m2", 0) < required_littered_lying_area_fattening(pen)
}

violations contains {
	"rule_id": "O622-SPACE-006",
	"message": sprintf("Gruppe %v, Bucht %v: Durchschnittsgewicht fehlt oder ist keiner Gewichtsklasse zuordenbar", [group_label(i, g), pen.pen_id]),
} if {
	some i, g in pig_groups
	is_fattening_group(g)
	some pen in group_pens(g)
	checked_pen(g, pen)
	not weight_class(object.get(pen, "average_weight_kg", null))
}

violations contains {
	"rule_id": "O622-SPACE-005",
	"message": sprintf("Gruppe %v, Bucht %v: nutzbare Gesamtfläche %v m² < gefordert %v m² (Sauen)", [group_label(i, g), pen.pen_id, effective_usable_area(pen), required_total_area_sows(pen)]),
} if {
	some i, g in pig_groups
	is_sow_group(g)
	some pen in group_pens(g)
	checked_pen(g, pen)
	effective_usable_area(pen) < required_total_area_sows(pen)
}

violations contains {
	"rule_id": "O622-SPACE-005",
	"message": sprintf("Gruppe %v, Bucht %v: eingestreute Liegefläche %v m² < gefordert %v m² (Sauen)", [group_label(i, g), pen.pen_id, object.get(pen, "littered_lying_area_m2", 0), required_lying_area_sows(pen)]),
} if {
	some i, g in pig_groups
	is_sow_group(g)
	some pen in group_pens(g)
	checked_pen(g, pen)
	object.get(pen, "littered_lying_area_m2", 0) < required_lying_area_sows(pen)
}

violations contains {
	"rule_id": "O622-LIE-001",
	"message": sprintf("Gruppe %v, Bucht %v: Liegefläche mit %v %% Perforation gilt nicht als planbefestigt (max. 5 %%)", [group_label(i, g), pen.pen_id, pen.lying_area_perforation_percent]),
} if {
	some i, g in pig_groups
	some pen in group_pens(g)
	checked_pen(g, pen)
	object.get(pen, "lying_area_perforation_percent", 0) > space.thresholds.max_perforation_percent_solid_lying_area
}

violations contains {
	"rule_id": "O622-LIE-002",
	"message": sprintf("Gruppe %v, Bucht %v: Liegebereich nicht so eingestreut, dass eine trockene Liegefläche gewährleistet ist", [group_label(i, g), pen.pen_id]),
} if {
	some i, g in pig_groups
	some pen in group_pens(g)
	checked_pen(g, pen)
	not object.get(pen, "lying_area_littered_and_dry", false) == true
}

violations contains {
	"rule_id": "O622-ENR-001",
	"message": sprintf("Gruppe %v, Bucht %v: kein ständig verfügbares Beschäftigungsmaterial (Gras, Stroh oder Heu)", [group_label(i, g), pen.pen_id]),
} if {
	some i, g in pig_groups
	some pen in group_pens(g)
	checked_pen(g, pen)
	not enrichment_ok(pen)
}

violations contains {
	"rule_id": "O622-GRP-001",
	"message": sprintf("Gruppe %v, Bucht %v: Tiere werden nicht in Gruppen gehalten", [group_label(i, g), pen.pen_id]),
} if {
	some i, g in pig_groups
	some pen in group_pens(g)
	checked_pen(g, pen)
	object.get(pen, "group_housed", true) == false
}

violations contains {
	"rule_id": "O622-STALL-001",
	"message": sprintf("Gruppe %v: Stall entspricht nicht der Stalldefinition (Verschalung/Windschutz, überdachte Liegeplätze, befestigter Boden, Sammelbehälter)", [group_label(i, g)]),
} if {
	some i, g in pig_groups
	stall_housed(g)
	st := object.get(g, ["housing", "stall", "structure"], {})
	object.get(st, "open_stall_system", false) == false
	not closed_stall_ok(st)
}

closed_stall_ok(st) if {
	st.three_sided_enclosure_or_windbreak == true
	st.lying_area_roofed == true
	st.paved_floor == true
	object.get(st, "liquid_manure_collectable", true) == true
}

violations contains {
	"rule_id": "O622-STALL-002",
	"message": sprintf("Gruppe %v: Offenstall ohne festes Dach über Liegeflächen, flüssigkeitsdichte Befestigung oder Sickerwasserableitung", [group_label(i, g)]),
} if {
	some i, g in pig_groups
	stall_housed(g)
	st := object.get(g, ["housing", "stall", "structure"], {})
	st.open_stall_system == true
	not open_stall_ok(st)
}

open_stall_ok(st) if {
	st.lying_area_roofed == true
	st.liquid_tight_paved == true
	st.seepage_to_collection_pit == true
}

violations contains {
	"rule_id": "O622-STALL-003",
	"message": sprintf("Gruppe %v: Stall bietet nicht für alle Tiere ausreichend Platz", [group_label(i, g)]),
} if {
	some i, g in pig_groups
	free_range_housed(g)
	stall_housed(g)
	object.get(g, ["housing", "stall", "structure", "space_for_all_animals"], true) == false
}

# ---------------------------------------------------------------------------
# Verstöße Gruppenhaltung Sauen und Einzeltierhaltung
# ---------------------------------------------------------------------------

violations contains {
	"rule_id": "O622-GRP-006",
	"message": sprintf("Gruppe %v: Gruppenhaltung beginnt erst %v Tage nach dem Decken (gefordert spätestens %v)", [group_label(i, g), sgh.group_from_day_after_mating, required_group_start_days_after_mating(sgh)]),
} if {
	some i, g in pig_groups
	is_sow_group(g)
	sgh := object.get(g, ["housing", "sow_group_housing"], null)
	is_object(sgh)
	sgh.group_from_day_after_mating > required_group_start_days_after_mating(sgh)
}

violations contains {
	"rule_id": "O622-GRP-006",
	"message": sprintf("Gruppe %v: Gruppenhaltung endet %v Tage vor dem Abferkeltermin (gefordert frühestens %v)", [group_label(i, g), sgh.group_until_days_before_farrowing, required_group_end_days_before_farrowing(sgh)]),
} if {
	some i, g in pig_groups
	is_sow_group(g)
	sgh := object.get(g, ["housing", "sow_group_housing"], null)
	is_object(sgh)
	sgh.group_until_days_before_farrowing > required_group_end_days_before_farrowing(sgh)
}

single_housing_events(g) := object.get(g, ["pig_welfare", "single_housing_events"], [])

violations contains {
	"rule_id": "O622-GRP-003",
	"message": sprintf("Gruppe %v: Einzeltierhaltung %v Tage (> 10 Tage) ohne Abmeldung des Tieres", [group_label(i, g), ev.days]),
} if {
	some i, g in pig_groups
	some ev in single_housing_events(g)
	ev.days > params.max_single_housing_days
	object.get(ev, "deregistered", false) == false
}

violations contains {
	"rule_id": "O622-GRP-002",
	"message": sprintf("Gruppe %v: Einzeltierhaltung ohne gesundheitlichen Grund oder ohne eingestreutes System (Prämienfähigkeit nicht gegeben)", [group_label(i, g)]),
} if {
	some i, g in pig_groups
	some ev in single_housing_events(g)
	ev.days <= params.max_single_housing_days
	not single_housing_short_ok(ev)
	object.get(ev, "deregistered", false) == false
}

single_housing_short_ok(ev) if {
	ev.health_reason == true
	ev.littered == true
}

violations contains {
	"rule_id": "O622-GRP-004",
	"message": sprintf("Gruppe %v: Krankheit/Verletzung und Dauer der Einzeltierhaltung nicht dokumentiert", [group_label(i, g)]),
} if {
	some i, g in pig_groups
	some ev in single_housing_events(g)
	object.get(ev, "documented", false) == false
}

# ---------------------------------------------------------------------------
# Teilnahme aller Tiere / bestehende Stallungen (O622-ALL-001 bis O622-ALL-003)
# ---------------------------------------------------------------------------

non_compliant_count(g) := count_basis(g) if object.get(g, ["pig_welfare", "continuous_compliance_from_eligible_weight"], true) == false

non_compliant_count(g) := object.get(g, ["pig_welfare", "non_compliant_average_count"], 0) if object.get(g, ["pig_welfare", "continuous_compliance_from_eligible_weight"], true) != false

violations contains {
	"rule_id": "O622-ALL-002",
	"message": sprintf("Gruppe %v: %v Tiere erfüllen die Haltungsbedingungen nicht durchgängig, aber nur %v abgemeldet", [group_label(i, g), non_compliant_count(g), deregistered_count(g)]),
} if {
	some i, g in pig_groups
	group_measure_category(g) in active_categories
	non_compliant_count(g) > deregistered_count(g)
}

# ---------------------------------------------------------------------------
# Verstöße Freilandhaltung
# ---------------------------------------------------------------------------

violations contains {
	"rule_id": "O622-FREE-001",
	"message": sprintf("Gruppe %v: Besatz %v GVE/ha überschreitet zulässige %v GVE/ha", [group_label(i, g), free_range_stocking_gve_per_ha(g), free_range_max_gve_per_ha(free_range(g))]),
} if {
	some i, g in pig_groups
	free_range_housed(g)
	free_range_stocking_gve_per_ha(g) > free_range_max_gve_per_ha(free_range(g))
}

violations contains {
	"rule_id": "O622-FREE-001",
	"message": sprintf("Gruppe %v: keine unbefestigte Freilandfläche angegeben", [group_label(i, g)]),
} if {
	some i, g in pig_groups
	free_range_housed(g)
	not free_range_reference_area_ha(free_range(g)) > 0
}

violations contains {
	"rule_id": "O622-FREE-002",
	"message": sprintf("Gruppe %v: durchgehende Nutzung der unbefestigten Fläche %v Monate (> 1 Jahr)", [group_label(i, g), free_range(g).continuous_use_months]),
} if {
	some i, g in pig_groups
	free_range_housed(g)
	object.get(free_range(g), "continuous_use_months", 0) > params.free_range_max_continuous_use_months
}

free_range_flag_rules := {
	"double_fence_or_solid_enclosure": "O622-FREE-003",
	"feed_and_water_separated": "O622-FREE-004",
	"feed_and_water_paved_or_moved_regularly": "O622-FREE-004",
	"feeding_place_roofed": "O622-FREE-004",
	"shelter_roofed_three_sided_littered": "O622-FREE-005",
	"shelter_all_animals_lie_simultaneously": "O622-FREE-005",
}

violations contains {
	"rule_id": rule_id,
	"message": sprintf("Gruppe %v: Freilandauflage '%v' nicht erfüllt", [group_label(i, g), flag]),
} if {
	some i, g in pig_groups
	free_range_housed(g)
	some flag, rule_id in free_range_flag_rules
	object.get(free_range(g), flag, false) != true
}

violations contains {
	"rule_id": "O622-FREE-006",
	"message": sprintf("Gruppe %v: keine Abferkelhütten für Zuchtsauen in Freilandhaltung", [group_label(i, g)]),
} if {
	some i, g in pig_groups
	free_range_housed(g)
	is_sow_group(g)
	object.get(free_range(g), "farrowing_on_range", false) == true
	object.get(free_range(g), "farrowing_huts_available", false) != true
}

violations contains {
	"rule_id": "O622-FREE-008",
	"message": sprintf("Gruppe %v: Freilandhaltung nicht laufend dokumentiert (Beginn/Ende je Schlag, Tierzahl je Schlag)", [group_label(i, g)]),
} if {
	some i, g in pig_groups
	free_range_housed(g)
	object.get(free_range(g), "records_complete", false) != true
}

violations contains {
	"rule_id": "O622-FREE-009",
	"message": sprintf("Gruppe %v: Wildschweine in Freilandhaltung sind nicht förderbar und abzumelden", [group_label(i, g)]),
} if {
	some i, g in pig_groups
	is_wild_boar(g)
	deregistered_count(g) < count_basis(g)
}

# O622-FREE-010: unbefestigte Ausläufe als "Sonstige Acker-/Grünlandflächen" beantragen.
violations contains {
	"rule_id": "O622-FREE-010",
	"message": sprintf("Schlag %v: unbefestigte Auslauffläche der Freilandschweinehaltung nicht als 'Sonstige Ackerflächen' oder 'Sonstige Grünlandflächen' beantragt", [p.parcel_id]),
} if {
	count(active_categories) > 0
	some p in object.get(input, ["land", "parcels"], [])
	object.get(p, "pig_free_range_run", false) == true
	not object.get(p, "mfa_land_use_type", "") in lists.free_range_run_land_use_types
}

# Modul: o6_22 – Teilnahme, Beantragung, Vertrag und Zugangsvoraussetzungen
package oepul.o6_22

# ---------------------------------------------------------------------------
# Beantragung (O622-APP-001, O622-APP-002, O622-APP-003, O622-APP-007)
# ---------------------------------------------------------------------------

# O622-APP-001: Beantragung im Maßnahmenantrag bis spätestens 31. Dezember vor
# dem ersten Förderjahr.
application_in_time(app) if {
	app.applied_on <= year_date(app.first_year - 1, params.application_deadline_mm_dd)
}

# O622-APP-002 / O622-APP-003: letzter Einstieg Kategorien 2027, Zuschläge 2028.
application_entry_year_allowed(app) if {
	application_code_row(app.code).kind == "category"
	app.first_year <= params.last_category_entry_year
}

application_entry_year_allowed(app) if {
	application_code_row(app.code).kind == "surcharge"
	app.first_year <= params.last_surcharge_entry_year
}

# O622-FMK-001: Festmistkompostierung erst ab dem Antragsjahr 2025.
application_surcharge_year_allowed(app) if app.code != "festmistkompostierung"

application_surcharge_year_allowed(app) if {
	app.code == "festmistkompostierung"
	app.first_year >= params.festmist_surcharge_from_year
}

application_valid(app) if {
	application_code_row(app.code)
	application_in_time(app)
	application_entry_year_allowed(app)
	application_surcharge_year_allowed(app)
}

# O622-EXIT-002: Abmeldung im Zeitraum 1.1.–31.12. -> im Förderjahr nicht mehr gültig.
withdrawn_effective(app) if {
	w := object.get(app, "withdrawn_on", null)
	is_string(w)
	w <= year_date(year, params.commitment_end_mm_dd)
}

# O622-CONTRACT-002: einjährige Verträge verlängern sich automatisch.
application_active(app) if {
	app.first_year <= year
	not withdrawn_effective(app)
	application_valid(app)
}

active_codes := {app.code | some app in applications; application_active(app)}

active_categories := {c |
	some code in active_codes
	row := application_code_row(code)
	row.kind == "category"
	c := row.category
}

# ---------------------------------------------------------------------------
# GVE je Kategorie und Mindestteilnahme (O622-ELIG-001, O622-PREM-002)
# ---------------------------------------------------------------------------

category_gve[c] := r4(sum([group_gve_eligible(g) |
	some g in pig_groups
	group_measure_category(g) == c
])) if {
	some c in active_categories
}

participating_gve := r4(sum([gve | some c in active_categories; gve := category_gve[c]]))

# O622-ELIG-001: mindestens 2,00 GVE in Summe über alle beantragten Kategorien.
min_participation_met if participating_gve >= params.min_participation_gve

# O622-CONTRACT-003: Mindestteilnahme nicht eingehalten -> Vertrag erlischt.
measure_contract_lapsed if {
	count(active_categories) > 0
	not min_participation_met
}

# O622-CONTRACT-005: kein prämienfähiges Tier in einer Kategorie -> Vertrag der
# Kategorie erlischt automatisch.
lapsed_categories contains c if {
	some c in active_categories
	category_gve[c] <= 0
}

# ---------------------------------------------------------------------------
# Tiergesundheitsdienst (O622-TGD-001, O622-TGD-002, O622-TGD-003)
# ---------------------------------------------------------------------------

# Förderbare Schweine am Betrieb (alle prämienfähigen Tierliste-Kategorien).
farm_eligible_pig_gve := r4(sum([group_gve_declared(g) | some g in pig_groups]))

animal_health_service_required if farm_eligible_pig_gve > params.animal_health_service_threshold_gve

ahs := object.get(pig_farm, "animal_health_service", {})

ahs_required_start(y) := year_date(y, params.animal_health_service_2023_start_mm_dd) if y == 2023

ahs_required_start(y) := year_date(y, params.commitment_start_mm_dd) if y != 2023

animal_health_service_ok if {
	ahs.participates == true
	ahs.participation_from <= ahs_required_start(year)
	ahs.participation_to >= year_date(year, params.commitment_end_mm_dd)
}

# ---------------------------------------------------------------------------
# Förderwerbende Person, Betriebsmindestgröße, Übernahme
# ---------------------------------------------------------------------------

applicant := object.get(input, ["farm", "applicant"], {})

applicant_type_row(t) := row if {
	some row in general.eligible_applicant_types
	row.type == t
}

# O622-GEN-002: Gebietskörperschaften nicht förderwerbend (o6_22 ist keine Ausnahme);
# juristische Personen/Personenvereinigungen nur bis 25 % öffentlicher Beteiligung.
applicant_type_ok if {
	row := applicant_type_row(applicant.type)
	row.public_share_limit_applies == false
}

applicant_type_ok if {
	row := applicant_type_row(applicant.type)
	row.public_share_limit_applies == true
	object.get(applicant, "public_authority_share_percent", 0) <= params.public_authority_max_share_percent
}

# O622-GEN-003: aktiver Landwirt und landwirtschaftliche Tätigkeit.
applicant_ok if {
	applicant_type_ok
	object.get(applicant, "is_active_farmer", false) == true
}

# O622-GEN-004: Betriebsmindestgröße nur im ersten ÖPUL-Teilnahmejahr.
first_oepul_year if object.get(input, ["farm", "first_oepul_participation_year"], 0) == year

farm_min_size_ok if not first_oepul_year

farm_min_size_ok if {
	first_oepul_year
	object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= params.farm_min_size_protected_cultivation_ha
}

farm_min_size_ok if {
	first_oepul_year
	object.get(input, ["land", "total_area_ha"], 0) >= params.farm_min_size_agricultural_area_ha
}

takeover := object.get(measure_input, "takeover", {"is_takeover": false})

# O622-GEN-006: Übernahme nur in Einzelfällen (Betriebsauflösung, -teilung,
# -zusammenlegung); Tiere und Flächen vom selben Vorbetrieb.
takeover_ok if object.get(takeover, "is_takeover", false) == false

takeover_ok if {
	takeover.is_takeover == true
	takeover.reason in general.takeover_individual_case_reasons
	takeover.animals_and_areas_from_same_predecessor == true
}

# ---------------------------------------------------------------------------
# Kategorienzuordnung Eber (O622-CAT-004, O622-CAT-005)
# ---------------------------------------------------------------------------

# Jungeber zwischen 32 und 50 kg und nicht im Deckeinsatz befindliche Eber über
# 50 kg sind Jung- und Mastschweine; Zuchteber im Deckeinsatz sind nicht prämienfähig.
boar_measure_category(weight_kg, used_for_mating) := "mastschweine" if {
	weight_kg >= 32
	weight_kg < 50
	is_boolean(used_for_mating)
}

boar_measure_category(weight_kg, used_for_mating) := "mastschweine" if {
	weight_kg >= 50
	used_for_mating == false
}

boar_measure_category(weight_kg, used_for_mating) := "nicht_praemienfaehig" if {
	weight_kg >= 50
	used_for_mating == true
}

# O622-CAT-003 / O622-CAT-006: Jungsauen ab 50 kg erst ab dem Decken in der
# Kategorie Zuchtsauen; davor (und ausgemerzte Zuchttiere) Jung- und Mastschweine.
gilt_or_culled_measure_category(weight_kg, mated, culled) := "zuchtsauen" if {
	weight_kg >= 50
	mated == true
	culled == false
}

gilt_or_culled_measure_category(weight_kg, mated, culled) := "mastschweine" if {
	weight_kg >= 32
	mated == false
	is_boolean(culled)
}

gilt_or_culled_measure_category(weight_kg, mated, culled) := "mastschweine" if {
	weight_kg >= 32
	is_boolean(mated)
	culled == true
}

# ---------------------------------------------------------------------------
# Verstöße
# ---------------------------------------------------------------------------

violations contains {
	"rule_id": "O622-APP-001",
	"message": sprintf("Antrag '%v' für %v nicht bis 31.12. des Vorjahres gestellt (gestellt am %v)", [app.code, app.first_year, app.applied_on]),
} if {
	some app in applications
	application_code_row(app.code)
	not application_in_time(app)
}

violations contains {
	"rule_id": "O622-APP-002",
	"message": sprintf("Einstieg in Kategorie '%v' für Förderjahr %v nach dem letzten Einstiegsjahr 2027", [app.code, app.first_year]),
} if {
	some app in applications
	application_code_row(app.code).kind == "category"
	not application_entry_year_allowed(app)
}

violations contains {
	"rule_id": "O622-APP-003",
	"message": sprintf("Einstieg in Zuschlag '%v' für Förderjahr %v nach dem letzten Einstiegsjahr 2028", [app.code, app.first_year]),
} if {
	some app in applications
	application_code_row(app.code).kind == "surcharge"
	not application_entry_year_allowed(app)
}

violations contains {
	"rule_id": "O622-APP-008",
	"message": sprintf("Unbekannter Antragscode '%v' (z. B. Zuschlag unkupiert für Zuchtsauen nicht vorgesehen)", [app.code]),
} if {
	some app in applications
	not application_code_row(app.code)
}

violations contains {
	"rule_id": "O622-FMK-001",
	"message": "Zuschlag Festmistkompostierung ist erst ab dem Antragsjahr 2025 beantragbar",
} if {
	some app in applications
	app.code == "festmistkompostierung"
	not application_surcharge_year_allowed(app)
}

violations contains {
	"rule_id": "O622-ELIG-001",
	"message": sprintf("Mindestteilnahme nicht erreicht: %v GVE < 2,00 GVE über alle beantragten Kategorien", [participating_gve]),
} if {
	measure_contract_lapsed
}

violations contains {
	"rule_id": "O622-TGD-001",
	"message": sprintf("Über 10,00 GVE förderbare Schweine (%v GVE): ganzjährige Teilnahme an einem anerkannten Tiergesundheitsdienst erforderlich", [farm_eligible_pig_gve]),
} if {
	count(active_categories) > 0
	animal_health_service_required
	not animal_health_service_ok
}

violations contains {
	"rule_id": "O622-GEN-002",
	"message": "Förderwerbende Person nicht teilnahmeberechtigt (Rechtsform oder Beteiligung von Gebietskörperschaften > 25 %)",
} if {
	count(active_categories) > 0
	not applicant_type_ok
}

violations contains {
	"rule_id": "O622-GEN-003",
	"message": "Förderwerbende Person ist kein aktiver Landwirt",
} if {
	count(active_categories) > 0
	applicant_type_ok
	not applicant_ok
}

violations contains {
	"rule_id": "O622-GEN-004",
	"message": "Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr nicht erreicht (0,50 ha geschützter Anbau oder 1,50 ha)",
} if {
	count(active_categories) > 0
	not farm_min_size_ok
}

violations contains {
	"rule_id": "O622-GEN-006",
	"message": "Maßnahmenübernahme nur bei Betriebsauflösung, -teilung oder -zusammenlegung und mit Tieren und Flächen vom selben Vorbetrieb zulässig",
} if {
	not takeover_ok
}

violations contains {
	"rule_id": "O622-GEN-001",
	"message": sprintf("Gruppe %v: Tiere werden nicht in Österreich gehalten und sind nicht förderbar", [group_label(i, g)]),
} if {
	some i, g in pig_groups
	not kept_in_austria(g)
}

# Modul: o6_22 – Melde-, Antrags- und Dokumentationspflichten
package oepul.o6_22

# ---------------------------------------------------------------------------
# Tierliste (O622-APP-004, O622-APP-005, O622-REP-006)
# ---------------------------------------------------------------------------

# O622-APP-005: Tierliste bis spätestens 15. April des Antragsjahres.
violations contains {
	"rule_id": "O622-APP-005",
	"message": sprintf("Tierliste am %v eingereicht – Frist 15. April %v überschritten", [mfa.tierliste_submitted_on, year]),
} if {
	count(active_categories) > 0
	is_string(object.get(mfa, "tierliste_submitted_on", null))
	mfa.tierliste_submitted_on > year_date(year, params.tierliste_deadline_mm_dd)
}

# O622-APP-004: bei schwankenden Tierbeständen Durchschnittsbestand erfassen.
violations contains {
	"rule_id": "O622-APP-004",
	"message": "Schwankender Schweinebestand: Durchschnittstierliste für das Kalenderjahr erforderlich",
} if {
	count(active_categories) > 0
	object.get(mfa, "stock_fluctuates", false) == true
	not uses_average_list
}

average_list_corrections := object.get(mfa, "average_list_corrections", [])

# Korrektur bis zum Ablauf der vierwöchigen Einspruchsfrist nach Erhalt der Auszahlungsmitteilung.
correction_in_time(corr) if {
	notice := object.get(mfa, "payment_notice_received_on", null)
	is_string(notice)
	days_between(notice, corr.corrected_on) <= params.average_list_correction_period_days_after_payment_notice
}

correction_in_time(corr) if {
	not is_string(object.get(mfa, "payment_notice_received_on", null))
	is_string(corr.corrected_on)
}

violations contains {
	"rule_id": "O622-APP-004",
	"message": sprintf("Korrektur des Jahresdurchschnitts vom %v nach Ablauf der vierwöchigen Einspruchsfrist", [corr.corrected_on]),
} if {
	some corr in average_list_corrections
	not correction_in_time(corr)
}

violations contains {
	"rule_id": "O622-REP-006",
	"message": sprintf("Korrektur der Tierliste vom %v ohne hochgeladene Nachweise (Lieferscheine, Rechnungen, Bestandsverzeichnis)", [corr.corrected_on]),
} if {
	some corr in average_list_corrections
	object.get(corr, "proofs_uploaded", false) != true
}

# O622-REP-006 (2026): Nachweise sollten Verkaufsdatum, Anzahl und Verkaufsgewicht enthalten.
warnings contains {
	"rule_id": "O622-REP-006",
	"message": sprintf("Nachweis zur Korrektur vom %v sollte Angabe '%v' enthalten", [corr.corrected_on, field]),
} if {
	some corr in average_list_corrections
	object.get(corr, "reason", "") in lists.tierliste_correction_reasons
	some field in lists.tierliste_correction_proof_fields
	not field in object.get(corr, "proof_fields", [])
}

# O622-REP-006: Bestandsänderung durch Verkauf, Verendung, Schlachtung ohne Anpassung.
violations contains {
	"rule_id": "O622-REP-006",
	"message": "Anzahl beantragter Schweine durch Verkauf, Verendung oder Schlachtung geändert, Jahresdurchschnitt in der Tierliste jedoch nicht angepasst",
} if {
	count(active_categories) > 0
	object.get(mfa, "stock_change_by_sale_death_slaughter", false) == true
	count(average_list_corrections) == 0
	object.get(mfa, "average_reflects_stock_changes", false) != true
}

# ---------------------------------------------------------------------------
# Stallskizze und Belegungsplan (O622-DOC-001, O622-DOC-003)
# ---------------------------------------------------------------------------

stall_sketch_required if {
	year <= params.stall_sketch_required_until_year
	some g in pig_groups
	group_measure_category(g) in active_categories
	stall_housed(g)
}

violations contains {
	"rule_id": "O622-DOC-001",
	"message": "Bis einschließlich Antragsjahr 2024: Stallskizze und Belegungsplan je Kategorie und Stallabteil müssen am Betrieb aufliegen",
} if {
	stall_sketch_required
	object.get(pig_farm, ["documentation", "stall_sketch_and_occupancy_plan"], false) != true
}

# ---------------------------------------------------------------------------
# Meldungen an VIS (O622-REP-004, O622-REP-005)
# ---------------------------------------------------------------------------

violations contains {
	"rule_id": "O622-REP-004",
	"message": "Zu- und Abgänge von Schweinen sind nicht vollständig an das VIS gemeldet",
} if {
	count(pig_groups) > 0
	object.get(pig_farm, "vis_reports_complete", false) != true
}

# ---------------------------------------------------------------------------
# Abmeldung bei Nichteinhaltung (O622-REP-001, O622-REP-003)
# ---------------------------------------------------------------------------

# Nichteinhaltbare Haltung für einzelne Tiere -> umgehende Abmeldung (Beilage
# "Tierwohl – Weide/Stallhaltung"); bei Abmeldung keine Prämie (O622-REP-002).
violations contains {
	"rule_id": "O622-REP-001",
	"message": sprintf("Gruppe %v: Abmeldung nicht umgehend nach Eintritt der Nichteinhaltbarkeit erfolgt", [group_label(i, g)]),
} if {
	some i, g in pig_groups
	dereg := object.get(g, ["pig_welfare", "deregistration"], null)
	is_object(dereg)
	dereg.reported_immediately == false
}

# Modul: o6_22 – optionale Zuschläge (unkupiert, GVO-frei, Festmistkompostierung)
package oepul.o6_22

# ---------------------------------------------------------------------------
# Zuschlag unkupierte Tiere (O622-UNK-001 bis O622-UNK-004)
# ---------------------------------------------------------------------------

unkupiert_active_categories := {row.category |
	some code in active_codes
	row := application_code_row(code)
	row.surcharge == "unkupiert"
	row.category in active_categories
}

# Alle an der Kategorie teilnehmenden Tiere (Tierwohlstall) ganzjährig unkupiert.
group_all_undocked(g) if object.get(g, ["pig_welfare", "participating_animals_all_undocked_full_year"], false) == true

unkupiert_ok(c) if {
	c in unkupiert_active_categories
	every g in pig_groups {
		undocked_or_other_category(g, c)
	}
}

undocked_or_other_category(g, c) if not group_measure_category(g) == c

undocked_or_other_category(g, c) if {
	group_measure_category(g) == c
	group_all_undocked(g)
}

violations contains {
	"rule_id": "O622-UNK-001",
	"message": sprintf("Zuschlag unkupiert für Kategorie '%v': nicht alle teilnehmenden Tiere sind im gesamten Antragsjahr unkupiert", [c]),
} if {
	some c in unkupiert_active_categories
	not unkupiert_ok(c)
}

# ---------------------------------------------------------------------------
# Zuschlag GVO-freie Eiweißfuttermittel (O622-GVO-001 bis O622-GVO-005)
# ---------------------------------------------------------------------------

gvo_active if "gvo_frei" in active_codes

protein_feed := object.get(pig_farm, "protein_feed", {})

# O622-GVO-003: Eiweißfuttermittel-Definition (> 20 % Rohprotein in der Trockenmasse,
# Raufuttermittel ausgenommen).
is_protein_feed(feed) if {
	feed.type == "compound"
	feed.crude_protein_percent_dm > params.protein_feed_min_crude_protein_percent_dm_exclusive
}

is_protein_feed(feed) if {
	feed.type == "single_component"
	object.get(feed, "is_roughage", false) == false
	feed.typical_crude_protein_percent_dm > params.protein_feed_min_crude_protein_percent_dm_exclusive
}

# O622-GVO-001 / O622-GVO-005: GVO-frei und europäische Herkunft (Kontinent Europa).
feed_compliant(feed) if {
	feed.gmo_free == true
	feed.origin_continent == "europe"
}

# O622-GVO-004: Nachweis bei zugekauften Eiweißfuttermitteln.
feed_proof_ok(feed) if object.get(feed, "produced_on_farm", false) == true

feed_proof_ok(feed) if {
	object.get(feed, "produced_on_farm", false) == false
	object.get(feed, "proof_documents_available", false) == true
}

non_compliant_protein_feeds contains feed.name if {
	some feed in object.get(protein_feed, "feeds", [])
	is_protein_feed(feed)
	not feed_compliant(feed)
}

violations contains {
	"rule_id": "O622-GVO-001",
	"message": sprintf("Zuschlag GVO-frei: nicht konformes Eiweißfuttermittel '%v' am Betrieb gelagert oder verfüttert (gilt für alle Tierarten)", [name]),
} if {
	gvo_active
	some name in non_compliant_protein_feeds
}

violations contains {
	"rule_id": "O622-GVO-002",
	"message": "Zuschlag GVO-frei: Lagerung oder Verfütterung nicht konformer Eiweißfuttermittel (auch Restbestände, andere Tierarten) am Betrieb",
} if {
	gvo_active
	object.get(protein_feed, "non_compliant_protein_feed_stored_or_fed", false) == true
}

violations contains {
	"rule_id": "O622-GVO-004",
	"message": sprintf("Zuschlag GVO-frei: kein Herkunfts- bzw. GVO-Freiheitsnachweis für zugekauftes Eiweißfuttermittel '%v'", [feed.name]),
} if {
	gvo_active
	some feed in object.get(protein_feed, "feeds", [])
	is_protein_feed(feed)
	not feed_proof_ok(feed)
}

# ---------------------------------------------------------------------------
# Zuschlag Festmistkompostierung (O622-FMK-001 bis O622-FMK-010)
# ---------------------------------------------------------------------------

festmist_active if {
	"festmistkompostierung" in active_codes
	year >= params.festmist_surcharge_from_year
}

composting := object.get(pig_farm, "manure_composting", {})

sorted_turn_dates(heap) := sort(object.get(heap, "turn_dates", []))

turn_intervals_days(heap) := [d |
	dates := sorted_turn_dates(heap)
	some k in numbers.range(1, count(dates) - 1)
	d := days_between(dates[k - 1], dates[k])
]

# O622-FMK-003: mindestens zweimal im Abstand von >= 14 Kalendertagen umgesetzt.
turned_sufficiently(heap) if {
	count(sorted_turn_dates(heap)) >= params.compost_min_turnings
	every d in turn_intervals_days(heap) {
		d >= params.compost_min_turning_interval_days
	}
}

# O622-FMK-004 / O622-FMK-005: Kompostwender (am Betrieb oder überbetrieblich belegt);
# Miststreuer/gleichwertiges Gerät nur bei vollständigem Umsetzen; Frontlader unzulässig.
turning_device_ok(heap) if {
	heap.turning_device == "compost_turner"
	heap.device_on_farm_or_use_documented == true
}

turning_device_ok(heap) if {
	heap.turning_device in {"manure_spreader", "equivalent_device"}
	heap.device_on_farm_or_use_documented == true
	heap.heap_fully_turned == true
}

# O622-FMK-006 / O622-FMK-007: Mischung/Schichtung mit organischem Material der
# Feldproduktion oder Strauch-/Astschnitt, ohne Umsetzpflicht.
mixed_heap_ok(heap) if {
	heap.mixed_with_plant_material == true
	heap.plant_material_noteworthy_share == true
	heap.composting_procedure_applied == true
	object.get(heap, "straw_rich_manure_only", false) == false
}

heap_ok(heap) if {
	turned_sufficiently(heap)
	turning_device_ok(heap)
}

heap_ok(heap) if mixed_heap_ok(heap)

violations contains {
	"rule_id": "O622-FMK-002",
	"message": "Zuschlag Festmistkompostierung: nicht der gesamte am Betrieb anfallende Festmist (aller Tierarten) wird am Betrieb kompostiert",
} if {
	festmist_active
	object.get(composting, "all_solid_manure_composted_on_farm", false) != true
}

violations contains {
	"rule_id": "O622-FMK-003",
	"message": sprintf("Zuschlag Festmistkompostierung: Kompostmiete %v erfüllt weder Umsetzvorgaben (>= 2 x, >= 14 Tage, Kompostwender) noch die Vorgaben für Mischmieten", [heap.heap_id]),
} if {
	festmist_active
	some heap in object.get(composting, "heaps", [])
	not heap_ok(heap)
}

violations contains {
	"rule_id": "O622-FMK-003",
	"message": "Zuschlag Festmistkompostierung: keine Kompostmiete angegeben",
} if {
	festmist_active
	count(object.get(composting, "heaps", [])) == 0
}

violations contains {
	"rule_id": "O622-FMK-008",
	"message": "Zuschlag Festmistkompostierung: Anlage, Umsetzen, Ausbringung bzw. Abgabe des Komposts nicht dokumentiert",
} if {
	festmist_active
	object.get(composting, "records_complete", false) != true
}

violations contains {
	"rule_id": "O622-FMK-009",
	"message": "Zuschlag Festmistkompostierung: Vorgaben der Nitrat-Aktionsprogramm-Verordnung für Kompostmieten nicht eingehalten",
} if {
	festmist_active
	not napv_compost_storage_ok
}

# O622-FMK-009: NAPV § 6 Abs. 1 Z 3 – Lagerung zur Kompostierung auf unbefestigten
# Flächen nur bei Einhaltung von § 6 Abs. 7 Z 2, 4, 5 und 6 und abgedeckter Miete.
napv_compost_storage_ok if object.get(composting, "heaps_on_unpaved_ground", false) == false

napv_compost_storage_ok if {
	composting.heaps_on_unpaved_ground == true
	napv := object.get(composting, "napv", {})
	napv.distance_to_surface_water_m >= 25
	napv.flat_non_sandy_ground == true
	napv.no_runoff_risk_to_surface_water == true
	napv.not_waterlogged_soil == true
	napv.groundwater_distance_m > 1
	napv.heap_covered == true
}

violations contains {
	"rule_id": "O622-FMK-010",
	"message": "Zuschlag Festmistkompostierung kann für Kompostställe nicht gewährt werden",
} if {
	festmist_active
	object.get(composting, "is_compost_barn", false) == true
}

package oepul.o6_22_test

# Konformer Referenzbetrieb (Antragsjahr 2025) mit allen drei Kategorien und
# allen drei Zuschlägen.
base_input := {
	"farm": {
		"year": 2025,
		"first_oepul_participation_year": 2023,
		"applicant": {
			"type": "natural_person",
			"is_active_farmer": true,
			"public_authority_share_percent": 0,
		},
